'use strict';
const app=document.querySelector('#app'),dialog=document.querySelector('#recipe-dialog');
let state=null,session=null,page='dashboard',selectedDay=0,authMode='login',currentItem=null,alternatives=[];
const titles={settings:['Ваш план начинается здесь','Подберём привычные блюда под вашу цель, бюджет и ритм жизни.'],menu:['Меню без лишних решений','Всё на ближайшие дни. Блюдо можно заменить, а покупки пересчитаются.'],shopping:['Покупаем только нужное','Общий список для всего меню. Укажите, что уже есть дома.'],baskets:['Одна корзина. Пять вариантов.','Сравниваем сумму покупки целых упаковок, а не условную стоимость порций.']};
const money=k=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(k/100);
const num=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:1}).format(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateLabel=s=>s?new Date(s).toLocaleDateString('ru-RU'):'нет данных';
const labelMeal=m=>({breakfast:'Завтрак',lunch:'Обед',dinner:'Ужин',snack:'Перекус'}[m]);
const foodIcon='<svg viewBox="0 0 64 64" fill="none" aria-hidden="true"><ellipse cx="32" cy="37" rx="24" ry="18" stroke="currentColor" stroke-width="2"/><ellipse cx="32" cy="36" rx="17" ry="12" stroke="currentColor"/><path d="M22 35c-7-16 8-19 10-10-1-17 16-12 11-1 14-2 13 13 0 15-4 11-13 9-13 0-7 6-17 3-8-4Z" fill="currentColor" opacity=".3"/><path d="m28 40 13-14m-7 7-8-3m11 0 1-7" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>';
async function api(path,method='GET',body){const response=await fetch('/api'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok){const e=new Error(data.error||'Не удалось выполнить запрос');e.fields=data.fields||{};e.status=response.status;throw e;}return data;}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4500);}
function errorBox(e,selector='#page-error'){const box=document.querySelector(selector);if(box){box.textContent=e.message;box.tabIndex=-1;box.focus();}else toast(e.message);Object.entries(e.fields||{}).forEach(([key,value])=>{const el=document.querySelector(`[data-error="${key}"]`);if(el)el.textContent=typeof value==='string'?value:'Недостаточно подходящих рецептов';});}
async function busy(button,action){if(button)button.disabled=true;try{await action();}catch(e){errorBox(e);}finally{if(button&&button.isConnected)button.disabled=false;}}
function brand(){return '<div class="brand"><span class="mark">f</span><span>fit nutrition<small>SUPPLY · ПИТАНИЕ ПО ПЛАНУ</small></span></div>';}
function renderAuth(){app.innerHTML=`<main class="auth"><section class="auth-story">${brand()}<div><div class="eyebrow muted">Меньше забот о еде</div><h1>Ваше меню.<br>Ваша цель.<br>Ваш бюджет.</h1><p>Снижайте вес без ежедневного вопроса «что приготовить». Составьте меню, соберите список и сравните стоимость покупок.</p><div class="auth-art"><span>Знакомые блюда</span><span>Понятные расходы</span></div></div><p class="small">Учебный прототип · Ижевск<br>Пищевая ценность и цены в демонстрации условные.</p></section><section class="auth-form"><div class="auth-form-inner"><div class="eyebrow">FIT NUTRITION SUPPLY</div><h1>Начнём с вашего плана</h1><p class="muted">Меню и покупки сохранятся в вашем аккаунте.</p><div class="auth-tabs"><button data-auth-mode="login" class="${authMode==='login'?'active':''}">Вход</button><button data-auth-mode="register" class="${authMode==='register'?'active':''}">Регистрация</button></div><div id="page-error" class="error" role="alert"></div><form id="auth-form"><div class="field"><label for="email">Email</label><input id="email" type="email" name="email" required autocomplete="email" placeholder="you@example.ru"><span class="field-error" data-error="email"></span></div><div class="field"><label for="password">Пароль</label><input id="password" name="password" type="password" minlength="8" required autocomplete="${authMode==='login'?'current-password':'new-password'}" placeholder="Не менее 8 символов"><span class="field-error" data-error="password"></span></div><button type="submit">${authMode==='login'?'Войти':'Создать аккаунт'} →</button></form><div class="auth-bottom"><p class="small muted">Можно изучить сервис без регистрации. Для вас будет создан отдельный демонстрационный аккаунт.</p><button class="secondary demo" id="demo">Открыть демоверсию</button></div></div></section></main>`;
decorateRegistration();app.querySelectorAll('[data-auth-mode]').forEach(b=>b.onclick=()=>{authMode=b.dataset.authMode;renderAuth();});document.querySelector('#auth-form').onsubmit=e=>{e.preventDefault();busy(e.submitter,async()=>{await api('/auth/'+authMode,'POST',Object.fromEntries(new FormData(e.target)));await load();});};document.querySelector('#demo').onclick=e=>busy(e.target,async()=>{await api('/auth/demo','POST',{});await load();});}
function render(){if(!state)return renderAuth();if(!profileIsSaved()){page='onboarding';return renderOnboarding();}if(page==='onboarding')return renderOnboarding();if(page==='dashboard')return renderDashboard();if(page==='result')return renderPlanResult();const [title,sub]=titles[page];app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="place">◉ &nbsp; Ижевск</div><nav aria-label="Основная навигация">${[['dashboard','⌂','Главная'],['onboarding','◌','Мой профиль'],['settings','◌','Настройки плана'],['result','▤','Результат плана'],['menu','▦','Моё меню'],['shopping','≡','Список покупок'],['baskets','◇','Сравнить корзины']].map(([id,icon,label])=>`<button data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</button>`).join('')}</nav><div class="side-bottom">Питание под вашу цель<br>Без подписки на базовый сценарий<div class="separator"></div><div>${esc(session?.email?.startsWith('demo-')?'Демонстрационный аккаунт':session?.email)}</div><button id="logout">Выйти из аккаунта ↗</button></div></aside><main class="workspace"><div class="topbar"><span>Моё пространство / ${page==='settings'?'Настройки':page==='menu'?'Меню':page==='shopping'?'Покупки':'Корзины'}</span><span class="badge amber">Учебный прототип · тестовые данные</span></div><div class="page-head"><div><div class="eyebrow">${page==='settings'?'ПЕРВЫЙ ШАГ К ВАШЕЙ ЦЕЛИ':'ВАШ ПЛАН ПИТАНИЯ'}</div><h1>${title}</h1><p>${sub}</p></div></div><div id="page-error" class="error" role="alert"></div><div id="page-content"></div><div class="footer-note">Fit Nutrition Supply · Для взрослых, заинтересованных в снижении веса.<br>Учебный каталог: количества, КБЖУ и цены - демонстрационные данные. Не используйте рассчитанное меню как лечебный рацион.</div></main></div>`;const content=document.querySelector('#page-content');if(page==='settings')renderPlanForm(content);else if(!state.plan)content.innerHTML='<section class="panel empty"><h2>Здесь будет ваш план</h2><p>Укажите параметры и составьте меню. Из него появятся список продуктов и сравнение корзин.</p><button data-page="settings">Перейти к настройкам →</button></section>';else if(page==='menu')renderMenu(content);else if(page==='shopping')renderShopping(content);else renderBaskets(content);app.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{navigate(b.dataset.page);});const logout=document.querySelector('#logout');if(logout)logout.onclick=()=>busy(logout,async()=>{await api('/auth/logout','POST',{});state=null;renderAuth();});}
function field(id,label,value,type='number',extra=''){return `<div class="field"><label for="${id}">${label}</label><input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${extra} required><span class="field-error" data-error="${id}"></span></div>`;}
function select(id,label,value,options){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${options.map(([v,t])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${t}</option>`).join('')}</select><span class="field-error" data-error="${id}"></span></div>`;}
function renderMenu(el){const p=state.plan,s=p.settings;selectedDay=Math.min(selectedDay,p.days-1);const items=p.items.filter(i=>i.day===selectedDay),total=items.reduce((a,i)=>a+i.nutrition.kcal,0);el.innerHTML=`<div class="days" aria-label="Дни меню">${Array.from({length:p.days},(_,d)=>{const date=new Date(p.start_date+'T12:00:00');date.setDate(date.getDate()+d);return `<button data-day="${d}" class="${d===selectedDay?'active':''}" aria-pressed="${d===selectedDay}">${date.toLocaleDateString('ru-RU',{weekday:'short'})}<strong>${date.getDate()}</strong></button>`;}).join('')}</div><div class="two-col"><section class="panel"><div class="eyebrow">${dateLabel(new Date(new Date(p.start_date+'T12:00:00').getTime()+selectedDay*86400000).toISOString())} · ${s.meals} ПРИЁМА ПИЩИ</div>${items.map(i=>{const r=state.recipes.find(r=>r.id===i.recipe_id);return `<article class="meal"><div class="food-icon">${foodIcon}</div><div><span class="eyebrow">${labelMeal(r.meal)}</span><h3>${esc(r.name)}</h3><span class="sub">${r.minutes} мин &nbsp; · &nbsp; ${num(i.nutrition.kcal)} ккал</span></div><div class="meal-actions"><button class="secondary" data-recipe="${i.id}">Рецепт</button><button class="link" data-replace="${i.id}">Заменить ↗</button></div></article>`;}).join('')}</section><aside><section class="panel summary"><div class="eyebrow">СЕГОДНЯ ПО ПЛАНУ</div><div class="big">${num(total)} <span class="small">ккал</span></div><div class="progress"><span></span></div><p class="small muted">Цель ${num(s.target.kcal)} ккал / день</p><div class="metrics">${[['Белки','protein'],['Жиры','fat'],['Углеводы','carbs']].map(([label,key])=>`<div class="metric"><strong>${num(items.reduce((a,i)=>a+i.nutrition[key],0))} г</strong>${label}</div>`).join('')}</div><div class="separator"></div><button data-page="shopping">К списку покупок →</button></section><div class="note">При замене сохраняется энергетическая доля приёма пищи. Состав и размеры порций пересчитываются.</div></aside></div>`;el.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{selectedDay=Number(b.dataset.day);render();});el.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>openRecipe(b.dataset.recipe,false));el.querySelectorAll('[data-replace]').forEach(b=>b.onclick=()=>openRecipe(b.dataset.replace,true));}
async function openRecipe(id,replace){currentItem=state.plan.items.find(i=>i.id===id);const r=state.recipes.find(r=>r.id===currentItem.recipe_id);alternatives=[];dialog.innerHTML=`<div class="dialog-head"><div><span class="eyebrow">${labelMeal(r.meal)} · ${r.minutes} МИН</span><h2 id="recipe-title">${esc(r.name)}</h2></div><button class="secondary" id="close-dialog" aria-label="Закрыть рецепт">×</button></div><div id="dialog-error" class="error" role="alert"></div><div class="metrics">${[['Калории','kcal','ккал'],['Белки','protein','г'],['Жиры','fat','г']].map(([l,k,u])=>`<div class="metric"><strong>${num(currentItem.nutrition[k])} ${u}</strong>${l}</div>`).join('')}</div><div class="recipe-columns"><section><h3>Ингредиенты</h3>${Object.entries(r.ingredients).map(([id,amount])=>{const ing=state.ingredients.find(i=>i.id===id);return `<div class="ingredient-line"><span>${esc(ing.name)}</span><span>${num(amount*currentItem.scale)} ${ing.unit}</span></div>`;}).join('')}<p class="small muted">Количество на этот приём пищи. Учебный рецепт.</p></section><section><h3>Как приготовить</h3><ol>${r.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></section></div><button class="secondary" id="show-alternatives">Выбрать другое блюдо</button><section id="alternatives"></section>`;document.querySelector('#close-dialog').onclick=()=>dialog.close();document.querySelector('#show-alternatives').onclick=e=>busy(e.target,loadAlternatives);dialog.showModal();if(replace){try{await loadAlternatives();}catch(e){errorBox(e,'#dialog-error');}}}
async function loadAlternatives(){return loadReplacementAlternatives();}
function renderShopping(el){const categories=[...new Set(state.shopping.map(i=>i.category))];el.innerHTML=`<div class="two-col"><section class="panel"><div class="button-row"><h2>На ${state.plan.days} дней</h2><span class="badge">${state.shopping.length} продуктов</span></div><p class="small muted">«Есть дома» вводится в тех же единицах, что и потребность.</p>${categories.map(c=>`<h3 class="category">${esc(c)}</h3>${state.shopping.filter(i=>i.category===c).map(i=>`<div class="shopping-row ${i.purchased?'done':''}"><input type="checkbox" aria-label="${esc(i.name)} уже куплено" data-purchased="${i.id}" ${i.purchased?'checked':''}><div><label class="product-name" for="stock-${i.id}">${esc(i.name)}</label><div class="small muted">Всего ${num(i.required)} ${i.unit}</div></div><div><label class="small" for="stock-${i.id}">Есть дома, ${i.unit}</label><input id="stock-${i.id}" data-stock="${i.id}" type="number" min="0" max="1000000" step="0.1" value="${i.at_home}"></div><span class="needed">Купить <strong>${num(i.needed)} ${i.unit}</strong></span></div>`).join('')}`).join('')}</section><aside><section class="panel summary"><div class="eyebrow">ВСЁ В ОДНОМ СПИСКЕ</div><h2>Без лишних покупок</h2><p class="small muted">Одинаковые ингредиенты объединены. Домашние запасы и купленные продукты вычитаются из закупки.</p><button data-page="baskets">Сравнить корзины →</button><div class="separator"></div><button class="link" id="export-list">Скачать список CSV ↓</button></section></aside></div>`;el.querySelectorAll('[data-stock]').forEach(input=>input.onchange=()=>saveStock(input.dataset.stock,{amount:Number(input.value)},input));el.querySelectorAll('[data-purchased]').forEach(input=>input.onchange=()=>saveStock(input.dataset.purchased,{purchased:input.checked},input));document.querySelector('#export-list').onclick=()=>{const q=s=>'"'+String(s).replaceAll('"','""')+'"';const csv='\ufeffПродукт;К покупке;Единица\n'+state.shopping.map(i=>[i.name,i.needed,i.unit].map(q).join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='Список продуктов.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};}
async function saveStock(id,change,input){const line=state.shopping.find(i=>i.id===id);await busy(input,async()=>{state=await api('/pantry','PUT',{ingredient_id:id,amount:line.at_home,purchased:line.purchased,...change});render();toast('Список и стоимость обновлены');});}
function renderBaskets(el){const best=state.baskets.find(b=>b.id===state.recommended);el.innerHTML=`<div class="note amber">${esc(state.price_source)} Доставка и поездки не включены: сравнение моделирует самовывоз без дополнительных расходов.</div><div class="button-row"><button class="secondary" id="refresh-prices">Обновить тестовый набор</button><button class="link" id="simulate-failure">Показать сбой источника</button></div><div class="panel summary"><div class="eyebrow">${best?'ЛУЧШАЯ ПОЛНАЯ КОРЗИНА':'НЕТ ПОЛНОЙ КОРЗИНЫ'}</div><div class="big">${best?money(best.total_kopecks):'Недостаточно данных'}</div><p>${best?`${esc(best.name)} · ${best.over_budget_kopecks?`превышение бюджета на ${money(best.over_budget_kopecks)}`:`в бюджете, осталось ${money(Math.round(state.plan.settings.budget*100)-best.total_kopecks)}`}`:'Нельзя рекомендовать неполный набор как самый выгодный.'}</p>${state.saving_kopecks?`<span class="badge">На ${money(state.saving_kopecks)} дешевле следующей полной корзины</span>`:''}</div><div class="store-grid">${state.baskets.map(b=>`<article class="store ${b.id===state.recommended?'recommended':''}"><div class="store-top"><h3>${esc(b.name)}</h3><span class="badge ${b.complete?'':'red'}">${b.id===state.recommended?'Рекомендуем':b.complete?'Полная':'Неполная'}</span></div><div class="store-price">${money(b.total_kopecks)}</div><p class="small muted">${b.complete?'За все нужные упаковки':`Не хватает ${b.missing.length} позиций · сумма частичная`}<br>Самая старая цена: ${dateLabel(b.oldest_price)}${b.oldest_price&&Date.now()-new Date(b.oldest_price).getTime()>72*3600000?' · устарела':''}</p>${!b.complete?`<p class="small error">Нет: ${b.missing.map(id=>esc(state.ingredients.find(i=>i.id===id)?.name)).join(', ')}</p>`:''}<details><summary>Упаковки и стоимость (${b.positions.length})</summary>${b.positions.map(i=>`<div class="cost-line"><span>${esc(i.name)}<br><span class="muted">${i.packs} уп. × ${num(i.pack_size)} ${i.unit}<br>Цена упаковки ${money(i.price_kopecks)}<br>Остаток ${num(i.leftover)} ${i.unit}</span></span><strong>${money(i.cost_kopecks)}</strong></div>`).join('')}</details></article>`).join('')}</div>`;document.querySelector('#refresh-prices').onclick=e=>busy(e.target,async()=>{state=await api('/prices/refresh','POST',{});render();toast('Обновлена дата демонстрационных предложений');});document.querySelector('#simulate-failure').onclick=e=>busy(e.target,async()=>{await api('/prices/refresh','POST',{simulate_failure:true});});}
async function load(){session=await api('/session');if(!session.authenticated){state=null;renderAuth();return;}state=await api('/state');const requested=location.hash.slice(1);navigate(profileIsSaved()?(flowPages.has(requested)?requested:'dashboard'):'onboarding',true);}
load().catch(e=>{app.innerHTML='<main class="empty"><h1>Не удалось подключиться</h1><p>Проверьте, запущен ли сервер, и обновите страницу.</p></main>';toast(e.message);});
